/*
 * ACL_$GET_SID - the current process's original SID block
 *
 * Original address: 0x00E74C24
 * Size: 70 bytes (0x00E74C24 .. 0x00E74C69), the first routine of the
 * SAU2 map's second ACL_ code segment ("I E74C24 ACL_ size = 184").
 * Generated by: Claude Opus 5.5
 *
 * Frame (link.w A6,0x0; A2/A5 saved; A5 = 0xE86064, the FILE_ data
 * segment, unused):
 *   (0x8,A6)  sid_ret  36 bytes out
 *   (0xC,A6)  status
 *
 *   0x00E74C32-0x00E74C56  nine longwords of original_sids[PROC1_$CURRENT]
 *                          (0xE97294 - 0x6E84 + pid*0x24)
 *   0x00E74C5A-0x00E74C5E  *status = 0
 *
 * The earlier prototype had an ASID as argument 1; the routine takes no
 * ASID and always answers for the current process.  Only reached through
 * SVC_$TRAP2_TABLE (0x00E7B47A).
 */

#include "acl/acl_internal.h"

void ACL_$GET_SID(void *sid_ret, status_$t *status_ret)
{
    *(acl_sid_block_t *)sid_ret =
        ACL_$DATA.original_sids[(int16_t)PROC1_$CURRENT];       /* 0x00E74C54 */
    *status_ret = status_$ok;                                   /* 0x00E74C5E */
}
